Signed-off-by: Dave Jiang <dave.jiang@intel.com>

Here is the root cause:
The bug is a use-after-free in cxl_detach_ep() caused by missing lifetime guarantees between a child port and its parent port. When a child port is allocated, no reference is taken on the parent device, so the parent can be freed while the child still exists. During bottom-up removal, cxl_detach_ep() accesses parent_port after it may have been freed due to concurrent detach or cascading unregistration, leading to memory corruption.

Here is the patch:

 static void cxl_port_release(struct device *dev)
 {
 	struct cxl_port *port = to_cxl_port(dev);
 	unsigned long index;
 	struct cxl_ep *ep;

 	xa_for_each(&port->endpoints, index, ep)
 		cxl_ep_remove(port, ep);
 	xa_destroy(&port->endpoints);
 	xa_destroy(&port->dports);
 	xa_destroy(&port->regions);
 	ida_free(&cxl_port_ida, port->id);
-	if (is_cxl_root(port))
+
+	if (is_cxl_root(port)) {
 		kfree(to_cxl_root(port));
-	else
+	} else {
+		put_device(dev->parent);
 		kfree(port);
+	}
 }


 static struct cxl_port *cxl_port_alloc(struct device *uport_dev,
 				       struct cxl_dport *parent_dport)
 {
 	struct cxl_root *cxl_root __free(kfree) = NULL;
 	struct cxl_port *port, *_port __free(kfree) = NULL;
 	struct device *dev;
 	int rc;

 	/* No parent_dport, root cxl_port */
 	if (!parent_dport) {
 		cxl_root = kzalloc_obj(*cxl_root);
 		if (!cxl_root)
 			return ERR_PTR(-ENOMEM);
 	} else {
 		_port = kzalloc_obj(*port);
 		if (!_port)
 			return ERR_PTR(-ENOMEM);
 	}

 	rc = ida_alloc(&cxl_port_ida, GFP_KERNEL);
 	if (rc < 0)
 		return ERR_PTR(rc);

 	if (cxl_root)
 		port = &no_free_ptr(cxl_root)->port;
 	else
 		port = no_free_ptr(_port);

 	port->id = rc;
 	port->uport_dev = uport_dev;

 	/*
 	 * The top-level cxl_port "cxl_root" does not have a cxl_port as
 	 * its parent and it does not have any corresponding component
 	 * registers as its decode is described by a fixed platform
 	 * description.
 	 */
 	dev = &port->dev;
 	if (parent_dport) {
 		struct cxl_port *parent_port = parent_dport->port;
 		struct cxl_port *iter;

 		dev->parent = &parent_port->dev;
+		get_device(dev->parent);
 		port->depth = parent_port->depth + 1;
 		port->parent_dport = parent_dport;

 		/*
 		 * walk to the host bridge, or the first ancestor that knows
 		 * the host bridge
 		 */
 		iter = port;
 		while (!iter->host_bridge &&
 		       !is_cxl_root(to_cxl_port(iter->dev.parent)))
 			iter = to_cxl_port(iter->dev.parent);
 		if (iter->host_bridge)
 			port->host_bridge = iter->host_bridge;
 		else if (parent_dport->rch)
 			port->host_bridge = parent_dport->dport_dev;
 		else
 			port->host_bridge = iter->uport_dev;
 		dev_dbg(uport_dev, "host-bridge: %s\n",
 			dev_name(port->host_bridge));
 	} else
 		dev->parent = uport_dev;

 	ida_init(&port->decoder_ida);
 	port->hdm_end = -1;
 	port->commit_end = -1;
 	xa_init(&port->dports);
 	xa_init(&port->endpoints);
 	xa_init(&port->regions);
 	port->component_reg_phys = CXL_RESOURCE_NONE;

 	device_initialize(dev);
 	lockdep_set_class_and_subclass(&dev->mutex, &cxl_port_key, port->depth);
 	device_set_pm_not_required(dev);
 	dev->bus = &cxl_bus_type;
 	dev->type = &cxl_port_type;

 	return port;
 }



